	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1).call(this.frame_1).wait(7).call(this.frame_8).wait(4).call(this.frame_12).wait(1).call(this.frame_13).wait(5).call(this.frame_18).wait(7).call(this.frame_25).wait(13));

